/**
 * Why an argument fills no proven parameter.
 */
export type PairingReason = "spread" | "no_parameter" | "receiver" | "no_signature";

/**
 * What a callable's parameter is to its calls (`docs/graph-model.md`, "Typed records").
 */
export type ParameterKind = "positional" | "this" | "rest" | "positional_only" | "keyword_only" | "keywords";

/**
 * What hovering a call link shows.
 */
export type Peek = { 
/**
 * The key.
 */
key: string, 
/**
 * The block kind, or `entrance`.
 */
kind: string, 
/**
 * The display label or entrance title.
 */
name: string, 
/**
 * The qualified name of a block.
 */
qualifiedName: string | null, 
/**
 * The first written line of a block (its signature), when its source verified.
 */
signature: string | null, 
/**
 * The file.
 */
path: string, 
/**
 * The first line.
 */
line: number | null, 
/**
 * The file's language.
 */
language: Language | null, };

/**
 * What Add's preview pane and the map popover show for one result.
 */
export type Preview = { "kind": "block", 
/**
 * Its project.
 */
project: ProjectId, 
/**
 * Its card header.
 */
header: BlockHeader, 
/**
 * Its first lines (at most 5).
 */
code: PreviewCode, 
/**
 * The entrances it is reached from (at most 5 listed).
 */
reachedFrom: Listed<EntranceRef>, 
/**
 * The calls it makes, in source order (at most 8 listed).
 */
calls: Listed<PreviewCall>, 
/**
 * The definitions that call it, by path and line (at most 5 listed).
 */
calledBy: Listed<PreviewCaller>, } | { "kind": "entrance", 
/**
 * Its project.
 */
project: ProjectId, 
/**
 * Its card header.
 */
header: EntranceHeader, 
/**
 * The handlers it runs, in registration order (at most 8).
 */
handlers: Array<PreviewHandler>, 
/**
 * Where it is declared.
 */
declared: Declared, 
/**
 * The definitions in its activation closure.
 */
reaches: number, 
/**
 * The external modules its closure calls, most called first (at most 5).
 */
externalModules: Array<string>, };

/**
 * One call a block makes.
 */
export type PreviewCall = { 
/**
 * The written callee.
 */
name: string, 
/**
 * The target's key, when the call resolved.
 */
key: string | null, 
/**
 * The module of an external target.
 */
module: string | null, };

/**
 * One definition that calls a block.
 */
export type PreviewCaller = { 
/**
 * The calling definition's key.
 */
key: string, 
/**
 * Its qualified name (its file's path for a file-level call).
 */
name: string, 
/**
 * Its file.
 */
path: string, 
/**
 * Its first line.
 */
line: number, };

/**
 * The first lines of a block, as the peek sheet's page model.
 */
export type PreviewCode = { 
/**
 * The first line shown.
 */
startLine: number, 
/**
 * Where `text` begins in the file, in UTF-16 code units.
 */
textStart: number, 
/**
 * The text of the lines shown, terminators included.
 */
text: string, 
/**
 * The lines shown.
 */
lines: Array<CodeLine>, 
/**
 * Syntax colors overlapping them.
 */
spans: Array<CodeSpan>, };

/**
 * One handler an entrance runs.
 */
export type PreviewHandler = { 
/**
 * Its qualified name, or the handler as written when it didn't resolve.
 */
name: string, 
/**
 * Its key, when it resolved.
 */
key: string | null, 
/**
 * Its file, when it resolved.
 */
path: string | null, 
/**
 * Its first line, when it resolved.
 */
line: number | null, };

/**
 * What kind of problem a [`ProblemItem`] is.
 */
export type ProblemCategory = "settings" | "compile_failed" | "doesnt_parse" | "cant_read" | "discovery" | "input" | "cache" | "board";

/**
 * One entry in the Problems list.
 */
export type ProblemItem = { 
/**
 * What kind of problem.
 */
category: ProblemCategory, 
/**
 * The folder-relative path involved, or empty.
 */
path: string, 
/**
 * The one-based line, when known.
 */
line: number | null, 
/**
 * The one-based column in characters, when known.
 */
column: number | null, 
/**
 * What went wrong.
 */
message: string, 
/**
 * For a file: `last_good` (the graph shows its last version that parsed) or `failed`.
 */
fileState: FileState | null, };

/**
 * The arguments of a command about one project.
 */
export type ProjectArgs = { 
/**
 * The project.
 */
project: ProjectId, };

/**
 * A project's `unfold.toml`: its text and the settings it holds.
 */
export type ProjectConfig = { 
/**
 * Whether the file exists (absent means every default).
 */
exists: boolean, 
/**
 * The file's text.
 */
text: string | null, 
/**
 * The validated settings, unless the file is invalid.
 */
settings: SettingsView | null, 
/**
 * Why the file is invalid, with its position.
 */
error: SettingsProblem | null, };

/**
 * Home's Health line.
 */
export type ProjectHealth = { 
/**
 * Files that don't parse or can't be read.
 */
doesntParse: number, 
/**
 * Boards whose health has items.
 */
boardsNeedingReview: number, 
/**
 * The boards with health items, most items first (at most 20).
 */
boards: Array<BoardHealthCount>, };

/**
 * A project's id: `p-` and 10 characters of `[a-z2-7]`, random, assigned when the project is
 * added. It survives restarts.
 */
export type ProjectId = string;

/**
 * The arguments of a command about one block or entrance of a project.
 */
export type ProjectKeyArgs = { 
/**
 * The project.
 */
project: ProjectId, 
/**
 * The structural key.
 */
key: string, };

/**
 * One project's match counts (at most 2,000 per kind).
 */
export type ProjectMatches = { 
/**
 * The project.
 */
project: ProjectId, 
/**
 * Definitions that matched.
 */
definitions: number, 
/**
 * Entrances that matched.
 */
entrances: number, 
/**
 * Files that matched.
 */
files: number, };

/**
 * The arguments of a command about one path of a project.
 */
export type ProjectPathArgs = { 
/**
 * The project.
 */
project: ProjectId, 
/**
 * The path relative to the project's folder, `/`-separated (`""` for the folder itself).
 */
path: string, };

/**
 * One project row of the sidebar.
 */
export type ProjectRow = { 
/**
 * The project's id.
 */
id: ProjectId, 
/**
 * Its folder's name.
 */
name: string, 
/**
 * The canonical path of its folder.
 */
path: string, 
/**
 * Whether the row is expanded in the sidebar.
 */
expanded: boolean, 
/**
 * Whether the project is live (its engine is open).
 */
live: boolean, 
/**
 * Its state.
 */
state: ProjectState, };

/**
 * A project's state, as its row shows it: one indicator per row.
 *
 * A live project's state is derived from its [`GraphStatus`] and its problem count (the Problems
 * list less board health), first match wins: `failed` > `compiling` > `updating` >
 * `not_compiled` > `problems` (a nonzero count) > `current`. A resting project shows the last state it had while live.
 */
export type ProjectState = { "kind": "current" } | { "kind": "compiling", 
/**
 * Files finished.
 */
done: number, 
/**
 * Files to process (0 until discovery finishes).
 */
total: number, } | { "kind": "updating", 
/**
 * How many files changed, or `None` while checking the whole folder.
 */
files: number | null, } | { "kind": "problems", 
/**
 * How many: files that don't parse or can't be read, settings errors, discovery, input,
 * and cache problems, and a failed compile.
 */
count: number, } | { "kind": "not_compiled" } | { "kind": "failed", 
/**
 * Why.
 */
message: string, } | { "kind": "resting", 
/**
 * `current`, `problems`, `not_compiled`, or `failed`.
 */
last: ProjectState, 
/**
 * When that state was last seen, in milliseconds since the Unix epoch.
 */
atMs: number, } | { "kind": "unavailable", 
/**
 * Why, in words.
 */
reason: string, };

/**
 * Home's header, state line, and Health line for one project.
 */
export type ProjectSummary = { 
/**
 * The project.
 */
project: ProjectId, 
/**
 * Its folder's name.
 */
name: string, 
/**
 * The canonical path of its folder.
 */
path: string, 
/**
 * Its row state.
 */
state: ProjectState, 
/**
 * Its graph's status: the state line's state, and how the folder is watched.
 */
status: GraphStatus, 
/**
 * When the graph was last committed, in milliseconds since the Unix epoch.
 */
updatedAtMs: number | null, 
/**
 * Indexed files.
 */
files: number, 
/**
 * The languages graphed, sorted.
 */
languages: Array<Language>, 
/**
 * The Health line.
 */
health: ProjectHealth, };

/**
 * What a finished text search found in one project.
 */
export type ProjectTextMatches = { 
/**
 * The project.
 */
project: ProjectId, 
/**
 * Its files with matches.
 */
files: number, 
/**
 * Its matching lines streamed.
 */
matches: number, };

/**
 * A proposed step: an intended addition after a real step of a block card, clearly not a compiler
 * fact. It has no implementation source and is never signed.
 */
export type Proposal = { 
/**
 * Unique among the page's items.
 */
id: string, 
/**
 * The block card it belongs to.
 */
card: string, 
/**
 * The real step it goes after: a key inside the card's block. Guarded.
 */
after: Key, 
/**
 * For a step with several outgoing paths (a condition or a loop): which one.
 */
path?: ProposalPath, 
/**
 * What it would do, in words: one line, never blank, at most 120 characters
 * ([`MAX_PROPOSAL_TITLE`]).
 */
title: string, 
/**
 * Why, in words: never blank, at most 400 characters ([`MAX_PROPOSAL_REASON`]).
 */
reason?: string, 
/**
 * Who proposed it.
 */
author: Author, };

/**
 * Which path of a decision a proposed step goes on.
 */
export type ProposalPath = "yes" | "no" | "each" | "done";

