  "app_info",
  "file_view",
  "open_in_editor",
  "card",
  "peek",
  "relations",
  "callers",
  "preview",
  "board_refs",
  "line_labels",
  "call_contract",
  "type_definition",
  "type_uses",
  "search",
  "search_text",
  "list_boards",
  "read_board",
  "open_board",
